using System.ComponentModel.Composition;
using XrmToolBox.Extensibility;
using XrmToolBox.Extensibility.Interfaces;

namespace ThemeMigrator
{
    /// <summary>
    /// XrmToolBox entry point (discovered through MEF).
    /// Icons: Resources/icon32.png (SmallImageBase64) and Resources/icon80.png (BigImageBase64).
    /// </summary>
    [Export(typeof(IXrmToolBoxPlugin)),
     ExportMetadata("Name", "Theme Migrator"),
     ExportMetadata("Description", "Migrate classic themes and modern (New look) theme settings, with their logos and theme XML web resources, from a source to a target Dataverse environment, keeping the same GUIDs. Optionally publish and set as default."),
     ExportMetadata("SmallImageBase64", ""),
     ExportMetadata("BigImageBase64", ""),
     ExportMetadata("BackgroundColor", "#F4EEF8"),
     ExportMetadata("PrimaryFontColor", "#4B1A6E"),
     ExportMetadata("SecondaryFontColor", "#6B6B6B")]
    public class ThemeMigratorPlugin : PluginBase
    {
        public override IXrmToolBoxPluginControl GetControl()
        {
            return new ThemeMigratorControl();
        }
    }
}
